use std::{fs,collections::HashMap,time::Instant};
#[derive(Clone,Copy)]struct Node{k:u32,a:u32,b:u32,aux:u32}
fn u32at(b:&[u8],at:usize)->u32{u32::from_le_bytes(b[at..at+4].try_into().unwrap())}fn u64at(b:&[u8],at:usize)->u64{u64::from_le_bytes(b[at..at+8].try_into().unwrap())}
fn independent(nodes:&[Node],roots:&[u32],lo:usize,hi:usize)->Vec<u32>{let mut seen=vec![false;nodes.len()];let mut stack=roots[lo..hi].to_vec();while let Some(i)=stack.pop(){let i=i as usize;if seen[i]{continue;}seen[i]=true;let x=nodes[i];if x.k>=3{stack.push(x.a);stack.push(x.b);}}seen.into_iter().enumerate().filter_map(|(i,v)|v.then_some(i as u32)).collect()}
fn verify_reconstruction(nodes:&[Node],roots:&[u32],ids:&[u32],lo:usize,hi:usize){let mut map=vec![u32::MAX;nodes.len()];for(i,id)in ids.iter().enumerate(){assert_eq!(map[*id as usize],u32::MAX);map[*id as usize]=i as u32;}for(i,id)in ids.iter().enumerate(){let n=nodes[*id as usize];if n.k>=3{for ch in[n.a,n.b]{let rem=map[ch as usize];assert_ne!(rem,u32::MAX);assert!((rem as usize)<i);assert_eq!(ids[rem as usize],ch);}}}for r in &roots[lo..hi]{assert_ne!(map[*r as usize],u32::MAX);assert_eq!(ids[map[*r as usize]as usize],*r);}}
fn main(){let a:Vec<_>=std::env::args().collect();let start=Instant::now();let bin=fs::read(&a[1]).unwrap();assert_eq!(&bin[..8],b"MRMASK01");let n=u64at(&bin,8)as usize;let np=u64at(&bin,16)as usize;let nr=u64at(&bin,24)as usize;assert_eq!((np,nr),(1024,512));assert_eq!(bin.len(),32+16*n+4*nr);let mut nodes=Vec::with_capacity(n);for i in 0..n{let at=32+i*16;let x=Node{k:u32at(&bin,at),a:u32at(&bin,at+4),b:u32at(&bin,at+8),aux:u32at(&bin,at+12)};assert_eq!(x.aux,0);assert!(x.k<=5);if x.k==2{assert!((x.a as usize)<np);}if x.k>=3{assert!((x.a as usize)<i&&(x.b as usize)<i);}nodes.push(x);}let roots:Vec<u32>=(0..nr).map(|j|u32at(&bin,32+16*n+4*j)).collect();assert!(roots.iter().all(|r|(*r as usize)<n));drop(bin);let loaded=start.elapsed().as_secs_f64();
let mut reach=vec![[0u64;8];n];for(j,r)in roots.iter().enumerate(){reach[*r as usize][j/64]|=1u64<<(j%64);}for i in (0..n).rev(){let x=nodes[i];if x.k>=3{let value=reach[i];for c in[x.a,x.b]{for w in 0..8{reach[c as usize][w]|=value[w];}}}}let propagated=start.elapsed().as_secs_f64();
let mut hist=HashMap::<[u64;8],u64>::new();for v in &reach{*hist.entry(*v).or_default()+=1;}let mut counts:Vec<Vec<u64>>=(0..=6).map(|p|vec![0;nr/(1<<p)]).collect();for(v,weight)in &hist{for p in 0..=6{let size=1usize<<p;let mask=if p==6{u64::MAX}else{(1u64<<size)-1};for(w,word)in v.iter().enumerate(){for j in 0..64/size{if word>>(j*size)&mask!=0{counts[p][w*(64/size)+j]+=weight;}}}}}let counted=start.elapsed().as_secs_f64();
let mut summaries=Vec::new();let mut checks=Vec::new();for p in 0..=6{let size=1usize<<p;let arr=&counts[p];let mut ranked:Vec<_>=arr.iter().copied().enumerate().map(|(i,c)|(c,i)).collect();ranked.sort();for pos in [0,ranked.len()/2,ranked.len()-1]{let(expected,group)=ranked[pos];let lo=group*size;let hi=lo+size;let ids=independent(&nodes,&roots,lo,hi);assert_eq!(ids.len()as u64,expected);verify_reconstruction(&nodes,&roots,&ids,lo,hi);for id in &ids{let w=lo/64;let touched=if size==64{reach[*id as usize][w]!=0}else{reach[*id as usize][w]>>(lo%64)&((1u64<<size)-1)!=0};assert!(touched);}checks.push(serde_json::json!({"group_size":size,"root_begin":lo,"root_end_exclusive":hi,"nodes":ids.len(),"identity_reconstruction":"PASS","independent_DFS":"PASS"}));}summaries.push(serde_json::json!({"group_size":size,"groups":arr.len(),"min":ranked[0].0,"median":ranked[ranked.len()/2].0,"max":ranked[ranked.len()-1].0,"mean":arr.iter().sum::<u64>()as f64/arr.len()as f64,"total_groups_nodes":arr.iter().sum::<u64>(),"all_group_counts":arr}));}
let report=serde_json::json!({"status":"IMMUTABLE_ROOT_CONE_CENSUS_AND_IDENTITY_RECONSTRUCTION_PASS","source":a[1],"nodes":n,"ports":np,"roots":nr,"unique_roots":roots.iter().copied().collect::<std::collections::BTreeSet<_>>().len(),"dead_nodes":hist.get(&[0u64;8]).copied().unwrap_or(0),"distinct_root_ancestor_signatures":hist.len(),"group_cones":summaries,"independent_reconstruction_checks":checks,"load_s":loaded,"propagation_elapsed_s":propagated,"counting_elapsed_s":counted,"total_s":start.elapsed().as_secs_f64(),"not_claimed":["runtime speedup","production change","new source theorem"]});println!("{report}");}
